"""Pydantic models shared across the API layer.

Two things are defined here:

* ``TravelQuery`` - the validated request contract for ``POST /assess``.
* ``AssessmentResponse`` (plus its evidence sub-models) - the response envelope
  the frontend renders, the AI fusion layer fills in, and ``GET
  /evidence/{assessment_id}`` links back to.

The envelope deliberately has first-class fields for *evidence* and
*uncertainty* so the final answer can always be traced back to raw source data.

Two contract decisions worth stating out loud:

* ``AssessmentResponse.assessment_id`` is generated by the pipeline (a UUID4), not
  authored by the model. It is the key the stored record is filed under, so every
  response - including an explicit error state - can be traced to one record.
* ``EvidenceRef.value`` is always a string on the wire. Models routinely emit the
  native JSON scalar they read (``0.96``, ``32``, ``true``) instead of the string
  the schema asks for; the coercion happens once, here, rather than in every
  consumer. Objects and arrays are rejected instead of flattened: evidence is a
  scalar fact, and coercing a nested structure would hide a contract violation.
"""

from __future__ import annotations

import datetime
import uuid
from typing import Any, List, Optional

from pydantic import BaseModel, Field, field_validator

import config


class TravelQuery(BaseModel):
    """Validated user input: a US route and a travel date."""

    origin: str = Field(
        ..., min_length=2, max_length=120, description="Origin city or airport code."
    )
    destination: str = Field(
        ..., min_length=2, max_length=120, description="Destination city or airport code."
    )
    travel_date: datetime.date = Field(
        ..., description="Travel date in ISO format (YYYY-MM-DD)."
    )


class EvidenceRef(BaseModel):
    """A pointer to the exact raw data behind a single claim.

    ``value`` is a string on the wire, but the model may emit the native JSON
    scalar it read. A ``mode="before"`` validator stringifies ``int``/``float``/
    ``bool`` and maps ``None`` to ``"null"`` so every consumer sees one type;
    ``dict``/``list`` are rejected because evidence is a scalar fact, not a
    nested structure. ``str`` passes through untouched.
    """

    source: str = Field(..., description="Data source id, e.g. 'nws'.")
    evidence_id: Optional[str] = Field(
        None, description="Id of the normalized signal-envelope evidence entry."
    )
    field: Optional[str] = Field(
        None, description="Vendor field or derived key the value came from."
    )
    value: Optional[str] = Field(
        None,
        validate_default=True,
        description=(
            "The observed value, as text. Native JSON scalars emitted by the model "
            "are stringified on ingest; objects and arrays are rejected."
        ),
    )
    observed_at: Optional[str] = Field(
        None, description="ISO timestamp of the upstream observation, if given."
    )
    raw_response_path: Optional[str] = Field(
        None, description="Path to the raw logged response for full traceability."
    )

    @field_validator("value", mode="before")
    @classmethod
    def _stringify_scalar(cls, value: Any) -> Optional[str]:
        """Coerce one evidence value to text, or reject a non-scalar.

        ``Any`` because this runs before validation, on whatever the model wrote.
        The order matters: ``bool`` is an ``int`` in Python, so it is checked
        first, and floats go through ``str()`` (``0.96`` stays ``"0.96"``, never
        ``"0.960000"``).
        """
        if value is None:
            # ``None`` is a real, reportable fact ("the vendor published no value"),
            # so it becomes a token rather than disappearing into an empty string.
            return "null"
        if isinstance(value, bool):
            return "true" if value else "false"
        if isinstance(value, (int, float)):
            return str(value)
        if isinstance(value, str):
            return value
        if isinstance(value, dict):
            keys = ", ".join(sorted(str(key) for key in value)[:5]) or "none"
            raise ValueError(
                "evidence 'value' must be a scalar (string, number, boolean or "
                "null); received a JSON object with keys: {0}".format(keys)
            )
        if isinstance(value, (list, tuple, set)):
            raise ValueError(
                "evidence 'value' must be a scalar (string, number, boolean or "
                "null); received a JSON array of {0} item(s)".format(len(value))
            )
        raise ValueError(
            "evidence 'value' must be a scalar (string, number, boolean or null); "
            "received {0}".format(type(value).__name__)
        )


class RiskItem(BaseModel):
    """One identified disruption risk with its supporting evidence."""

    risk: str = Field(..., description="Short description of the risk.")
    severity: str = Field(
        ..., description=f"One of: {', '.join(config.RISK_LEVELS)}."
    )
    evidence: List[EvidenceRef] = Field(default_factory=list)
    confidence: Optional[float] = Field(
        None,
        ge=0.0,
        le=1.0,
        description=(
            "Numeric confidence (0.0-1.0) in this risk given the strength and "
            "agreement of the available signals. None when no numeric estimate "
            "can be justified from the data."
        ),
    )
    confidence_label: Optional[str] = Field(
        None, description="Qualitative companion label, e.g. 'medium'."
    )


class SourceStatus(BaseModel):
    """Per-source outcome, so missing signals are visible, not hidden."""

    source: str
    status: str = Field(
        ...,
        description=(
            "'ok' (all sub-queries succeeded, real signals), 'partial' (some "
            "sub-queries succeeded and some failed: real but incomplete signals), "
            "'unavailable' (source reachable but has no data for this query, e.g. "
            "plan limit), or 'error' (the call failed)."
        ),
    )
    error: Optional[str] = Field(
        None, description="Explicit reason when status is not 'ok'."
    )
    error_code: Optional[str] = Field(
        None,
        description=(
            "Machine-readable reason code from data_sources.base.ErrorCode, e.g. "
            "'plan_limit', 'timeout', 'malformed_payload'. On a partial source this "
            "is the first failure; see error_codes for the full list."
        ),
    )
    error_codes: List[str] = Field(
        default_factory=list,
        description=(
            "Every failure code recorded for this source. One entry for error/"
            "unavailable, one per failed sub-query for partial, empty for ok."
        ),
    )
    latency_ms: Optional[float] = None
    records: Optional[int] = Field(None, description="Number of records returned.")
    raw_response_path: Optional[str] = None
    consulted_at: Optional[str] = None


class AssessmentResponse(BaseModel):
    """The end-to-end response contract.

    ``assessment_id`` is minted by the pipeline (a UUID4) so the response can be
    linked to the record persisted under ``logs/assessments/{assessment_id}.json``.
    It is deliberately not a model-authored field: the model never sees it, and
    fusion discards it if a model returns one.
    """

    assessment_id: str = Field(
        default_factory=lambda: str(uuid.uuid4()),
        description=(
            "UUID4 identifying this assessment; use it with "
            "GET /evidence/{assessment_id} to read the stored record."
        ),
    )
    status: str = Field(
        ...,
        description=(
            "One of: 'ok' (all sources), 'partial' (some sources failed), "
            "'error' (no assessment could be produced)."
        ),
    )
    fusion_error_code: Optional[str] = Field(
        None,
        description=(
            "Stable, machine-readable reason fusion produced no assessment; None "
            "when fusion succeeded (including when the status is 'partial' only "
            "because a *source* was degraded). Codes: 'not_ready', 'no_signals', "
            "'no_evidence', 'raw_logging_failed', 'unexpected_error', 'timeout', "
            "'transport_error', 'rate_limited', 'provider_error', "
            "'invalid_response'. Set by the pipeline, never by the model, so a "
            "caller can branch on the cause instead of matching prose."
        ),
    )
    schema_version: str = Field(default=config.SCHEMA_VERSION)
    origin: Optional[str] = None
    destination: Optional[str] = None
    travel_date: Optional[str] = None
    risk_level: Optional[str] = Field(
        None, description=f"One of: {', '.join(config.RISK_LEVELS)}."
    )
    confidence: Optional[float] = Field(
        None,
        ge=0.0,
        le=1.0,
        description=(
            "Numeric confidence (0.0-1.0) in the overall risk level, degraded by "
            "missing or stale sources. None when no estimate is justified."
        ),
    )
    confidence_label: Optional[str] = Field(
        None, description="Qualitative companion label, e.g. 'medium'."
    )
    summary: Optional[str] = Field(
        None, description="Plain-language assessment, or the error explanation."
    )
    risks: List[RiskItem] = Field(default_factory=list)
    recommended_actions: List[str] = Field(default_factory=list)
    uncertainty: List[str] = Field(
        default_factory=list,
        description="Explicit limitations: missing sources, stale data, assumptions.",
    )
    sources: List[SourceStatus] = Field(default_factory=list)
    missing_credentials: List[str] = Field(default_factory=list)
    generated_at: Optional[str] = None
